// Pre-built apps showcase: two tabs that auto-advance on a progress timer, with stacked screenshots
// that shuffle when the active app changes. Clicking a tab or the back card stops the auto-advance.
// Port of ProductsApps.tsx; markup is generated by port-landing.mjs.

const AUTO_ADVANCE_MS = 5000;
const C = 'products-apps-';

export function initApps(root) {
  const apps = JSON.parse(root.querySelector('.products-apps-data')?.textContent ?? '[]');
  const tabs = Array.from(root.querySelectorAll(`.${C}tab`));
  if (apps.length === 0 || tabs.length === 0) {
    return undefined;
  }

  const ids = apps.map((app) => app.id);
  const tabFor = (id) => tabs.find((tab) => tab.id === `apps-tab-${id}`);
  const cardFor = (id) => root.querySelector(`#apps-panel-${id}`);

  const state = { activeId: ids[0], frontId: ids[0], isAnimating: false, isPaused: false };
  // The server-rendered progress bar is already playing for the first tab
  let progressKey = `play-${ids[0]}`;

  function render(previousActiveId) {
    const { activeId, frontId, isAnimating, isPaused } = state;

    for (const id of ids) {
      const tab = tabFor(id);
      const isActive = id === activeId;
      tab.classList.toggle(`${C}tab-active`, isActive);
      tab.setAttribute('aria-selected', String(isActive));

      const card = cardFor(id);
      const isFront = id === frontId;
      card.classList.toggle(`${C}stack-front`, !isAnimating && isFront);
      card.classList.toggle(`${C}stack-back`, !isAnimating && !isFront);
      card.classList.toggle(`${C}anim-to-front`, isAnimating && id === activeId && id !== frontId);
      card.classList.toggle(`${C}anim-to-back`, isAnimating && id === frontId && id !== activeId);
      card.setAttribute('aria-selected', String(isFront));
    }

    // Progress bar: (re)mounted whenever its React key would change, which restarts the CSS animation
    const nextKey = isPaused ? 'paused' : `play-${activeId}`;
    if (nextKey !== progressKey || previousActiveId !== activeId) {
      root.querySelectorAll(`.${C}tab-progress`).forEach((el) => el.remove());
      const progress = document.createElement('span');
      progress.className = `${C}tab-progress` + (isPaused ? ` ${C}tab-progress-full` : '');
      progress.setAttribute('aria-hidden', 'true');
      if (!isPaused) {
        progress.style.animationDuration = `${AUTO_ADVANCE_MS}ms`;
      }
      tabFor(activeId).appendChild(progress);
      progressKey = nextKey;
    }

    // Description: remounted on change (React keys it by app id)
    if (previousActiveId !== activeId) {
      const description = root.querySelector(`.${C}app-description`);
      const next = description.cloneNode(false);
      next.textContent = apps.find((app) => app.id === activeId).body;
      description.replaceWith(next);
    }
  }

  function goToTab(id) {
    if (id === state.activeId || state.isAnimating) {
      return;
    }
    const previous = state.activeId;
    state.activeId = id;
    if (id !== state.frontId) {
      if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) {
        state.frontId = id;
      } else {
        state.isAnimating = true;
      }
    }
    render(previous);
  }

  function select(id) {
    const previous = state.activeId;
    state.isPaused = true;
    render(previous);
    goToTab(id);
  }

  root.addEventListener('click', (e) => {
    const tab = e.target.closest(`.${C}tab`);
    if (tab) {
      select(tab.id.replace('apps-tab-', ''));
      return;
    }
    const card = e.target.closest(`.${C}stack-card`);
    if (card) {
      const id = card.id.replace('apps-panel-', '');
      select(ids.find((other) => other !== id));
    }
  });

  root.addEventListener('animationend', (e) => {
    if (e.target.classList.contains(`${C}tab-progress`) && !state.isPaused) {
      goToTab(ids[(ids.indexOf(state.activeId) + 1) % ids.length]);
    } else if (e.target.classList.contains(`${C}anim-to-front`) && state.isAnimating) {
      const previous = state.activeId;
      state.frontId = state.activeId;
      state.isAnimating = false;
      render(previous);
    }
  });

  return undefined;
}
